import 'package:flutter/material.dart';import '../theme/app_theme.dart';
class ChatScreen extends StatefulWidget{const ChatScreen({super.key});@override State<ChatScreen> createState()=>_ChatScreenState();}
class _ChatScreenState extends State<ChatScreen>{final input=TextEditingController();final messages=<String>['SYSTEM|Selamat datang di Global Chat Business Cargo Simulator.','ADIEXPRESS|Siap membangun jaringan logistik dunia.'];@override void dispose(){input.dispose();super.dispose();}@override Widget build(BuildContext context)=>Column(children:[Container(padding:const EdgeInsets.all(12),color:AppColors.surface,child:const Row(children:[Icon(Icons.public,color:AppColors.emerald),SizedBox(width:8),Text('GLOBAL CHAT • LEVEL 1',style:TextStyle(fontWeight:FontWeight.w900))])),Expanded(child:ListView(padding:const EdgeInsets.all(12),children:messages.map((m){final p=m.split('|');return Container(margin:const EdgeInsets.only(bottom:9),padding:const EdgeInsets.all(11),decoration:BoxDecoration(color:AppColors.surface,borderRadius:BorderRadius.circular(12),border:Border.all(color:AppColors.border)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(p.first,style:const TextStyle(color:AppColors.emerald,fontSize:9,fontWeight:FontWeight.w900)),const SizedBox(height:5),Text(p.last)]));}).toList())),Container(padding:const EdgeInsets.all(9),decoration:const BoxDecoration(color:AppColors.surface,border:Border(top:BorderSide(color:AppColors.border))),child:Row(children:[Expanded(child:TextField(controller:input,maxLength:180,decoration:const InputDecoration(counterText:'',hintText:'Tulis pesan...'))),IconButton.filled(onPressed:(){final m=input.text.trim();if(m.isNotEmpty)setState((){messages.add('ADIEXPRESS|'+m);input.clear();});},icon:const Icon(Icons.send),style:IconButton.styleFrom(backgroundColor:AppColors.emerald,foregroundColor:AppColors.background))]))]);}}